// monta o pedido ao Gemini para a mensagem de follow-up (1 item = 1 dono com pergunta parada)
const j = $input.item.json;
const hist = (Array.isArray(j.historico) ? j.historico : []).map(h => (h.role === 'user' ? 'DONO: ' : 'GIULIA: ') + String(h.content || '').replace(/\s+/g, ' ').substring(0, 500)).join('\n');
const inv = Array.isArray(j.invoices_abertas) && j.invoices_abertas.length ? JSON.stringify(j.invoices_abertas).substring(0, 3500) : '(nenhuma)';
const ant = Array.isArray(j.invoices_anteriores) && j.invoices_anteriores.length ? JSON.stringify(j.invoices_anteriores).substring(0, 1500) : '(nenhuma)';
const idi = String(j.idioma || 'pt-BR').toLowerCase().startsWith('en') ? 'ingles' : (String(j.idioma || '').toLowerCase().startsWith('es') ? 'espanhol' : 'portugues do Brasil');
const sys = `Voce e a Giulia, secretaria virtual no WhatsApp. Voce fez uma pergunta ao ${j.nome || 'dono'} ha ${j.minutos} minutos e ele nao respondeu.
Escreva UMA mensagem curta de WhatsApp (no maximo 6 linhas), em ${idi}, tom leve e direto:
1) comece perguntando se ficou alguma duvida no que voce perguntou;
2) em uma frase, mostre que entendeu o pedido dele (cite o cliente e as pecas/o que ele quer);
3) diga so o que ainda falta, em forma de pergunta de sim/nao quando der, sugerindo a resposta mais provavel com base no historico:
   - acabamento que ele sempre usa nas invoices anteriores (ex.: 'tudo Savana, como nas outras?');
   - cliente com o mesmo primeiro nome de uma invoice anterior: pergunte se e a mesma pessoa e cite a cidade dela;
   - modelo com nome parecido do catalogo (ex.: 'o Bisbi e o Bixby I?'); se o rascunho listar opcoes, cite-as;
   - TAMANHO: para cada peca cujo modelo tem MAIS DE UM tamanho no CATALOGO e ele nao disse o tamanho, pergunte qual (cite as opcoes) - junte tudo numa pergunta so;
4) feche dizendo que ele pode responder por audio.
NUNCA cite preco, total, imposto ou valor. NUNCA invente dado que nao esteja abaixo. Sem titulo, sem lista longa, sem markdown alem de *negrito*. Responda SO com o texto da mensagem.`;
const catT = j.catalogo_tamanhos ? `\n\nCATALOGO (modelo e tamanhos que existem - use para resolver ambiguidade: se ele disse o tamanho e so um modelo tem esse tamanho, sugira esse):\n${String(j.catalogo_tamanhos).substring(0, 2500)}` : '';
const ctx = `PERGUNTA PARADA (sua ultima mensagem):\n${String(j.pergunta || '').substring(0, 1500)}\n\nINVOICES EM ABERTO (rascunho atual):\n${inv}\n\nINVOICES ANTERIORES DELE:\n${ant}\n\nCONVERSA RECENTE (mais antiga primeiro):\n${hist}${catT}`;
return { json: { ...j, gemini_body: {
  systemInstruction: { parts: [{ text: sys }] },
  contents: [{ role: 'user', parts: [{ text: ctx }] }],
  generationConfig: { temperature: 0.4, maxOutputTokens: 4096 } } } };

// texto final (ignora partes de raciocinio do modelo) + trava: nada de preco/cifrao
const g = $input.item.json || {};
const base = $('Montar Prompt Followup').item.json;
let txt = '';
try { txt = ((g.candidates || [])[0].content.parts || []).filter(p => p && p.text && !p.thought).map(p => p.text).join('').trim(); } catch (e) {}
txt = txt.replace(/^["']|["']$/g, '').trim();
txt = txt.replace(/\*\*/g, '*');   // WhatsApp usa *negrito* simples
let fim = ''; try { fim = String((g.candidates || [])[0].finishReason || ''); } catch (e) {}
const ok = fim === 'STOP' && txt.length >= 15 && txt.length <= 900 && !/(\$|US\$|R\$|USD)\s?\d/.test(txt);
return { json: { ok, send_to: base.from_numero, texto: txt, pergunta_id: base.pergunta_id } };

// grava o follow-up na memoria (metadata followup=true: nao dispara de novo e o WF01 ve o que foi dito)
const env = $input.item.json || {};
const m = $('Montar Envio').item.json;
const esc = s => String(s == null ? '' : s).replace(/'/g, "''").replace(/\$+/g, x => x.length === 1 ? "' || chr(36) || '" : "' || repeat(chr(36), " + x.length + ") || '");
if (env.error || !m.ok) return { json: { sql: 'SELECT 1;' } };
const meta = '{"followup": true, "pergunta_id": ' + parseInt(m.pergunta_id, 10) + '}';
// item 1: rascunho de invoice aberto ganha +24h a partir do follow-up (nao expira enquanto a gente espera ele)
const prorroga = "UPDATE hz_invoices_pendentes SET expira_em = GREATEST(expira_em, NOW() + INTERVAL '24 hours') WHERE dono_numero = '" + esc(m.send_to) + "' AND invoice_id IS NULL AND status IN ('incompleto', 'aguardando_confirmacao') AND expira_em > NOW();";
return { json: { sql: "INSERT INTO giulia_memoria (role, content, from_numero, metadata) VALUES ('assistant', '" + esc(m.texto) + "', '" + esc(m.send_to) + "', '" + meta + "'::jsonb);\n" + prorroga } };

// 09/11: Gemini -> Claude Opus 5.5. Converte o gemini_body montado acima no corpo da API do Claude.
const j = $input.item.json;
const gb = j.gemini_body || {};
const sys = ((gb.systemInstruction || {}).parts || []).map(p => p.text || '').filter(Boolean).join('\n');
const msgs = [];
for (const c of (gb.contents || [])) {
  const role = c.role === 'model' ? 'assistant' : 'user';
  const content = [];
  for (const p of (c.parts || [])) {
    if (p.text) content.push({ type: 'text', text: p.text });
    const d = p.inline_data || p.inlineData;
    if (d && d.data) {
      const mt = String(d.mime_type || d.mimeType || '').toLowerCase().split(';')[0].trim();
      if (/^image\/(jpeg|jpg|png|gif|webp)$/.test(mt)) content.push({ type: 'image', source: { type: 'base64', media_type: mt === 'image/jpg' ? 'image/jpeg' : mt, data: d.data } });
      else if (mt === 'application/pdf') content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: d.data } });
      else if (mt.startsWith('text/')) { let t = ''; try { t = Buffer.from(d.data, 'base64').toString('utf8'); } catch (e) {} content.push({ type: 'text', text: 'Conteudo do arquivo:\n' + t.substring(0, 100000) }); }
      else content.push({ type: 'text', text: '[anexo ' + (mt || 'desconhecido') + ' que nao consigo ler]' });
    }
  }
  if (!content.length) content.push({ type: 'text', text: '(vazio)' });
  if (msgs.length && msgs[msgs.length - 1].role === role) msgs[msgs.length - 1].content.push(...content);
  else msgs.push({ role, content });
}
if (!msgs.length || msgs[0].role !== 'user') msgs.unshift({ role: 'user', content: [{ type: 'text', text: '(inicio)' }] });
if (msgs[msgs.length - 1].role !== 'user') msgs.push({ role: 'user', content: [{ type: 'text', text: 'Continue.' }] });
const gc = gb.generationConfig || {};
const ehJson = String(gc.responseMimeType || '').includes('json');
const claude_body = {
  model: 'claude-opus-5-5',
  // o Opus 5.5 sempre pensa antes de responder e o raciocinio conta no max_tokens: folga sobre o limite antigo
  max_tokens: Math.max(4000, Math.min(16000, (parseInt(gc.maxOutputTokens, 10) || 4000) * 2)),
  system: sys + (ehJson ? '\n\nResponda SOMENTE com o objeto JSON pedido acima, sem texto antes ou depois e sem bloco de codigo.' : ''),
  messages: msgs,
  output_config: { effort: 'low' },
  fallbacks: 'default'
};
if (!claude_body.system) delete claude_body.system;  // a API recusa system vazio
return { json: { ...j, claude_body } };

// 09/11: resposta do Claude -> formato que o codigo abaixo ja le (candidates/parts/finishReason)
const r = $input.item.json || {};
if (r.error || !Array.isArray(r.content)) {
  return { json: r.error ? r : { error: { message: 'Claude sem content: ' + JSON.stringify(r).substring(0, 300) } } };
}
const text = r.content.filter(b => b && b.type === 'text').map(b => b.text || '').join('');
const fr = ({ end_turn: 'STOP', stop_sequence: 'STOP', max_tokens: 'MAX_TOKENS', refusal: 'SAFETY' })[r.stop_reason] || String(r.stop_reason || '').toUpperCase();
const u = r.usage || {};
return { json: {
  candidates: [{ content: { role: 'model', parts: [{ text }] }, finishReason: fr }],
  usageMetadata: { promptTokenCount: (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0), candidatesTokenCount: u.output_tokens || 0 },
  modelVersion: r.model || 'claude', claude_stop_reason: r.stop_reason || null
} };
